// Smena (qolip) retsept bo‘yicha siro sarfi: reja vs haqiqiy (ortiqcha)\nmodel ShiftMaterialUsage {\n  id            String      @id @default(cuid())\n  shiftId       String\n  shift         ShiftRecord @relation(fields: [shiftId], references: [id], onDelete: Cascade)\n  rawMaterialId String\n  rawMaterial   RawMaterial @relation(fields: [rawMaterialId], references: [id], onDelete: Restrict)\n  expectedKg    Float       @default(0)\n  actualKg      Float       @default(0)\n  deltaKg       Float       @default(0)\n  createdAt     DateTime    @default(now())\n\n  @@unique([shiftId, rawMaterialId])\n  @@index([rawMaterialId])\n}\n\nmodel Client {\n  id                   String            @id @default(cuid())\n  name                 String\n  phone                String            @unique\n  address              String?\n  bankAccount          String?\n  bankName             String?\n  stir                 String?\n  /// Mijoz oldindan to‘lagan mablag‘ (kassa kirim)\n  cashBalance          Float             @default(0)\n  /// Chop etish uchun — mijoz bo‘yicha default\n  deliveryVehiclePlate String?\n  deliveryDriverName   String?\n  status               EntityStatus      @default(COMPLETED)\n  createdAt            DateTime          @default(now())\n  updatedAt            DateTime          @updatedAt\n  orders               Order[]\n  payments             Payment[]\n  bankTransactions     BankTransaction[]\n  kassaEntries         KassaEntry[]\n}\n\nmodel Order {\n  id           String       @id @default(cuid())\n  clientId     String\n  client       Client       @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  createdById  String?\n  createdBy    User?        @relation(\"OrderCreator\", fields: [createdById], references: [id], onDelete: SetNull)\n  status       OrderStatus  @default(PENDING)\n  totalAmount  Float        @default(0)\n  paidAmount   Float        @default(0)\n  debtAmount   Float        @default(0)\n  /// Sotuv sanasi (UI dagi sana)\n 